#!/usr/bin/env node
/**
 * Imports the committed UniPlus fixture into Shopify as draft products.
 *
 * The fixture is generated by scripts/build-uniplus-fixture.mjs from the client
 * workbook and the local photoshoot folder. ProductSet is used by handle so a
 * re-run updates the same products and variants. Prices are only written when the
 * fixture has one; missing prices become 0.00 and keep the product in DRAFT.
 *
 * Run:
 *   node --env-file=.env.local scripts/import-uniplus-catalog.mjs --dry-run
 *   node --env-file=.env.local scripts/import-uniplus-catalog.mjs --upload
 *   node --env-file=.env.local scripts/import-uniplus-catalog.mjs --only=tucked-jacket
 *   node --env-file=.env.local scripts/import-uniplus-catalog.mjs --report
 *
 * Flags:
 *   --dry-run          Print the planned writes and exit without calling Shopify.
 *   --upload           Upload local images (default).
 *   --no-upload        Update products without replacing media.
 *   --publish          Publish products that have no launch blockers. Never publishes a blocked product.
 *   --collections-only Sync collection membership without touching products or media.
 *   --verify-only      Verify existing products and write the report without writing.
 *   --limit=<number>   Import the first N selected products.
 *   --only=<handles>   Comma-separated product handles.
 *   --report[=<path>]  Report path, default .catalog-import/uniplus-report.json.
 *   --image-dir=<path> Local photoshoot folder, default ~/UniPlus/Lorum Ipsum resources.
 */

import { existsSync, mkdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, extname, join } from "node:path";
import { fileURLToPath } from "node:url";

const args = parseArgs(process.argv.slice(2));
const domain = process.env.NEXT_PUBLIC_SHOPIFY_STORE_DOMAIN;
const version = process.env.SHOPIFY_API_VERSION ?? "2026-10";
const dryRun = Boolean(args["dry-run"]) || process.env.DRY_RUN === "1";
const upload = args.upload !== false && !args["no-upload"];
const publish = Boolean(args.publish);
const collectionsOnly = Boolean(args["collections-only"]);
const verifyOnly = Boolean(args["verify-only"]);
const staticToken = process.env.SHOPIFY_ADMIN_ACCESS_TOKEN;
const clientId = process.env.SHOPIFY_CLIENT_ID;
const clientSecret = process.env.SHOPIFY_CLIENT_SECRET;
const imageDir =
  typeof args["image-dir"] === "string"
    ? args["image-dir"]
    : join(homedir(), "UniPlus", "Lorum Ipsum resources");
const reportPath =
  typeof args.report === "string" ? args.report : ".catalog-import/uniplus-report.json";
const onlyHandles = args.only
  ? new Set(
      String(args.only)
        .split(",")
        .map((handle) => handle.trim())
        .filter(Boolean),
    )
  : null;
const limit = args.limit ? Number(args.limit) : null;
const fixturePath = join(dirname(fileURLToPath(import.meta.url)), "data", "uniplus-catalog.json");

if (!dryRun && (!domain || (!staticToken && !(clientId && clientSecret)))) {
  console.error(
    "Set NEXT_PUBLIC_SHOPIFY_STORE_DOMAIN and either SHOPIFY_ADMIN_ACCESS_TOKEN or SHOPIFY_CLIENT_ID + SHOPIFY_CLIENT_SECRET.",
  );
  process.exit(1);
}

const endpoint = domain ? `https://${domain}/admin/api/${version}/graphql.json` : null;
let accessToken = staticToken;

function parseArgs(argv) {
  const parsed = {};
  for (const arg of argv) {
    if (!arg.startsWith("--")) continue;
    const [key, ...rest] = arg.slice(2).split("=");
    parsed[key] = rest.length > 0 ? rest.join("=") : true;
  }
  return parsed;
}

function sleep(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

async function getAccessToken() {
  if (accessToken) return accessToken;
  const response = await fetch(`https://${domain}/admin/oauth/access_token`, {
    body: new URLSearchParams({
      client_id: clientId,
      client_secret: clientSecret,
      grant_type: "client_credentials",
    }),
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    method: "POST",
  });
  const payload = await response.json();
  if (!response.ok || !payload.access_token) {
    throw new Error(`Client credentials grant failed: ${JSON.stringify(payload)}`);
  }
  accessToken = payload.access_token;
  return accessToken;
}

async function admin(query, variables = {}, attempt = 0) {
  const token = await getAccessToken();
  const response = await fetch(endpoint, {
    body: JSON.stringify({ query, variables }),
    headers: {
      "Content-Type": "application/json",
      "X-Shopify-Access-Token": token,
    },
    method: "POST",
  });
  const text = await response.text();
  let payload;
  try {
    payload = JSON.parse(text);
  } catch {
    throw new Error(
      `Shopify Admin API returned non-JSON (${response.status}): ${text.slice(0, 300)}`,
    );
  }

  const throttled = payload.errors?.some(
    (error) => error.extensions?.code === "THROTTLED" || /throttled/i.test(error.message ?? ""),
  );
  if ((response.status === 429 || response.status >= 500 || throttled) && attempt < 5) {
    const wait = 1000 * 2 ** attempt;
    console.warn(`Shopify Admin API ${response.status || "throttled"}; retrying in ${wait}ms`);
    await sleep(wait);
    return admin(query, variables, attempt + 1);
  }
  if (!response.ok) {
    throw new Error(`Shopify Admin API ${response.status}: ${text.slice(0, 800)}`);
  }
  if (payload.errors?.length) {
    throw new Error(`Shopify Admin GraphQL errors: ${JSON.stringify(payload.errors, null, 2)}`);
  }

  const available = payload.extensions?.cost?.throttleStatus?.currentlyAvailable;
  if (typeof available === "number" && available < 250) await sleep(1000);
  return payload.data;
}

const PRODUCT_BY_HANDLE = `#graphql
  query ProductByHandle($query: String!) {
    products(first: 5, query: $query) {
      nodes {
        id
        handle
        status
        mediaCount { count }
        variantsCount { count }
        options { name values }
        media(first: 100) { nodes { id } }
        variants(first: 100) {
          nodes {
            id
            sku
            price
            selectedOptions { name value }
          }
        }
      }
    }
  }
`;

const PRODUCT_SET = `#graphql
  mutation ProductSet($identifier: ProductSetIdentifiers, $input: ProductSetInput!, $synchronous: Boolean!) {
    productSet(identifier: $identifier, input: $input, synchronous: $synchronous) {
      product {
        id
        handle
        status
        mediaCount { count }
        variantsCount { count }
      }
      userErrors { field message code }
    }
  }
`;

const LIST_PRODUCTS = `#graphql
  query ListProducts($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      nodes { id handle }
      pageInfo { hasNextPage endCursor }
    }
  }
`;

const PRODUCT_DELETE_MEDIA = `#graphql
  mutation ProductDeleteMedia($productId: ID!, $mediaIds: [ID!]!) {
    productDeleteMedia(productId: $productId, mediaIds: $mediaIds) {
      deletedMediaIds
      userErrors { field message }
    }
  }
`;

const STAGED_UPLOADS_CREATE = `#graphql
  mutation StagedUploadsCreate($input: [StagedUploadInput!]!) {
    stagedUploadsCreate(input: $input) {
      stagedTargets {
        url
        resourceUrl
        parameters { name value }
      }
      userErrors { field message }
    }
  }
`;

const METAFIELDS_SET = `#graphql
  mutation MetafieldsSet($metafields: [MetafieldsSetInput!]!) {
    metafieldsSet(metafields: $metafields) {
      metafields { id namespace key }
      userErrors { field message code }
    }
  }
`;

const FIND_COLLECTION = `#graphql
  query FindCollection($query: String!) {
    collections(first: 2, query: $query) {
      nodes { id handle title }
    }
  }
`;

const COLLECTION_CREATE = `#graphql
  mutation CollectionCreate($input: CollectionInput!) {
    collectionCreate(input: $input) {
      collection { id handle }
      userErrors { field message }
    }
  }
`;

const COLLECTION_PRODUCTS = `#graphql
  query CollectionProducts($id: ID!, $after: String) {
    collection(id: $id) {
      products(first: 250, after: $after) {
        nodes { id handle }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
`;

const COLLECTION_BY_HANDLE = `#graphql
  query CollectionByHandle($query: String!) {
    collections(first: 2, query: $query) {
      nodes { id handle }
    }
  }
`;

const COLLECTION_ADD = `#graphql
  mutation CollectionAddProducts($id: ID!, $productIds: [ID!]!) {
    collectionAddProducts(id: $id, productIds: $productIds) {
      collection { id handle }
      userErrors { field message }
    }
  }
`;

const SHOP_SETTINGS = `#graphql
  query ShopSettings {
    shop { name currencyCode }
  }
`;

const PUBLICATIONS = `#graphql
  query Publications {
    publications(first: 20) { nodes { id name } }
  }
`;

const PUBLISHABLE_PUBLISH = `#graphql
  mutation PublishablePublish($id: ID!, $input: [PublicationInput!]!) {
    publishablePublish(id: $id, input: $input) {
      userErrors { field message }
    }
  }
`;

const VERIFY_PRODUCTS = `#graphql
  query VerifyProducts($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      nodes {
        id
        handle
        status
        mediaCount { count }
        options { name values }
        variants(first: 100) {
          nodes {
            sku
            price
            selectedOptions { name value }
          }
        }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
`;

function safeFilenamePart(value) {
  return String(value)
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

function imageMimeType(path) {
  const extension = extname(path).toLowerCase();
  if (extension === ".png") return "image/png";
  if (extension === ".webp") return "image/webp";
  if (extension === ".gif") return "image/gif";
  if (extension === ".avif") return "image/avif";
  return "image/jpeg";
}

function selectedProducts(fixture) {
  let products = fixture.products;
  if (onlyHandles) products = products.filter((product) => onlyHandles.has(product.handle));
  if (limit) products = products.slice(0, limit);
  return products;
}

function buildProductInput(product) {
  const imageInputs = new Map();
  const files = product.images.map((image, index) => {
    const extension = extname(image.localFile).toLowerCase();
    const filename = `${product.handle}-${String(index + 1).padStart(2, "0")}-${safeFilenamePart(image.uid)}${extension}`;
    const file = {
      alt: image.alt ?? `${product.title} ${image.view}`,
      contentType: "IMAGE",
      filename,
      originalSource: null,
    };
    imageInputs.set(image.uid, file);
    return file;
  });

  const optionValuesByVariant = product.variants.map((variant) => [
    { name: variant.colour, optionName: "Colour" },
    { name: variant.size, optionName: "Size" },
  ]);

  const variants = product.variants.map((variant, index) => {
    const colourway = product.colourways.find((entry) => entry.name === variant.colour);
    const firstImageUid = colourway?.images[0];
    const file = firstImageUid ? imageInputs.get(firstImageUid) : null;
    const price = variant.price == null ? "0.00" : String(variant.price);
    const result = {
      inventoryItem: {
        sku: variant.sku,
        tracked: false,
      },
      inventoryPolicy: variant.continueSelling ? "CONTINUE" : "DENY",
      optionValues: optionValuesByVariant[index],
      position: index + 1,
      price,
    };
    if (variant.barcode) result.barcode = variant.barcode;
    if (variant.compareAtPrice) result.compareAtPrice = String(variant.compareAtPrice);
    if (file) result.file = file;
    return result;
  });

  const input = {
    descriptionHtml: product.descriptionHtml ?? undefined,
    files,
    handle: product.handle,
    productOptions: [
      {
        name: "Colour",
        position: 1,
        values: product.colourways.map((colourway) => ({ name: colourway.name })),
      },
      {
        name: "Size",
        position: 2,
        values: ["XS", "S", "M", "L", "XL", "XXL"].map((name) => ({ name })),
      },
    ],
    productType: product.productType ?? undefined,
    seo: product.seo.title || product.seo.description ? product.seo : undefined,
    status: "DRAFT",
    tags: product.tags,
    title: product.title,
    variants,
    vendor: product.vendor ?? undefined,
  };
  return input;
}

async function stageImage(product, image) {
  const path = join(imageDir, image.localFile);
  if (!existsSync(path)) {
    throw new Error(`${product.handle}: local image missing ${path}`);
  }
  const mimeType = imageMimeType(path);
  const filename = `${product.handle}-${safeFilenamePart(image.uid)}${extname(path).toLowerCase()}`;
  const size = statSync(path).size;
  const data = await admin(STAGED_UPLOADS_CREATE, {
    input: [
      {
        fileSize: String(size),
        filename,
        httpMethod: "POST",
        mimeType,
        resource: "IMAGE",
      },
    ],
  });
  const errors = data.stagedUploadsCreate.userErrors;
  if (errors.length) throw new Error(`${product.handle}: ${JSON.stringify(errors)}`);
  const target = data.stagedUploadsCreate.stagedTargets[0];
  if (!target?.url || !target.resourceUrl) {
    throw new Error(`${product.handle}: staged upload returned no target`);
  }

  const body = new FormData();
  for (const parameter of target.parameters) body.append(parameter.name, parameter.value);
  body.append("file", new Blob([readFileSync(path)], { type: mimeType }), filename);

  const response = await fetch(target.url, { body, method: "POST" });
  if (!response.ok) {
    throw new Error(`${product.handle}: staged upload failed ${response.status}`);
  }
  return {
    alt: image.alt ?? `${product.title} ${image.view}`,
    contentType: "IMAGE",
    filename,
    originalSource: target.resourceUrl,
  };
}

async function findProduct(handle) {
  const data = await admin(PRODUCT_BY_HANDLE, { query: `handle:${handle}` });
  return data.products.nodes.find((node) => node.handle === handle) ?? null;
}

async function listProductIds() {
  const ids = new Map();
  let after = null;
  do {
    const data = await admin(LIST_PRODUCTS, { after, first: 250 });
    for (const product of data.products.nodes) ids.set(product.handle, product.id);
    after = data.products.pageInfo.hasNextPage ? data.products.pageInfo.endCursor : null;
  } while (after);
  return ids;
}

async function deleteMedia(product) {
  const mediaIds = product.media.nodes.map((node) => node.id);
  if (mediaIds.length === 0) return 0;
  const data = await admin(PRODUCT_DELETE_MEDIA, {
    mediaIds,
    productId: product.id,
  });
  const errors = data.productDeleteMedia.userErrors;
  if (errors.length) throw new Error(`${product.handle}: ${JSON.stringify(errors)}`);
  return data.productDeleteMedia.deletedMediaIds.length;
}

async function setMetafields(product, productId) {
  const metafields = [];
  if (product.countryOfOrigin) {
    metafields.push({
      key: "origin",
      namespace: "custom",
      ownerId: productId,
      type: "single_line_text_field",
      value: product.countryOfOrigin,
    });
  }
  if (product.composition) {
    metafields.push({
      key: "composition",
      namespace: "custom",
      ownerId: productId,
      type: "multi_line_text_field",
      value: product.composition,
    });
  }
  if (product.care) {
    metafields.push({
      key: "care",
      namespace: "custom",
      ownerId: productId,
      type: "multi_line_text_field",
      value: product.care,
    });
  }
  if (product.fit) {
    metafields.push({
      key: "fit",
      namespace: "custom",
      ownerId: productId,
      type: "single_line_text_field",
      value: product.fit,
    });
  }
  if (metafields.length === 0) return 0;
  const data = await admin(METAFIELDS_SET, { metafields });
  const errors = data.metafieldsSet.userErrors;
  if (errors.length) throw new Error(`${product.handle}: ${JSON.stringify(errors)}`);
  return data.metafieldsSet.metafields.length;
}

async function findCollection(handle) {
  const data = await admin(FIND_COLLECTION, { query: `handle:${handle}` });
  return data.collections.nodes.find((node) => node.handle === handle) ?? null;
}

async function collectionProductIds(collectionId) {
  const ids = [];
  let after = null;
  do {
    const data = await admin(COLLECTION_PRODUCTS, { after, id: collectionId });
    ids.push(...data.collection.products.nodes.map((node) => node.id));
    after = data.collection.products.pageInfo.hasNextPage
      ? data.collection.products.pageInfo.endCursor
      : null;
  } while (after);
  return ids;
}

async function ensureCollection(collection) {
  const existing = await findCollection(collection.handle);
  if (existing) return { created: false, id: existing.id };
  const data = await admin(COLLECTION_CREATE, {
    input: { handle: collection.handle, title: collection.title },
  });
  const errors = data.collectionCreate.userErrors;
  if (errors.length) throw new Error(`${collection.handle}: ${JSON.stringify(errors)}`);
  return { created: true, id: data.collectionCreate.collection.id };
}

async function getPublicationId() {
  if (process.env.SHOPIFY_PUBLICATION_ID) return process.env.SHOPIFY_PUBLICATION_ID;
  const data = await admin(PUBLICATIONS);
  const match = data.publications.nodes.find((node) =>
    /headless|hydrogen|storefront/i.test(node.name),
  );
  return match?.id ?? null;
}

async function publishProduct(productId) {
  const publicationId = await getPublicationId();
  if (!publicationId) {
    console.warn("No Headless publication found; product status is ACTIVE but not published.");
    return false;
  }
  const data = await admin(PUBLISHABLE_PUBLISH, {
    id: productId,
    input: [{ publicationId }],
  });
  const errors = data.publishablePublish.userErrors;
  if (errors.length) throw new Error(`publish ${productId}: ${JSON.stringify(errors)}`);
  return true;
}

async function importProduct(product, options) {
  const existing = options.dryRun ? null : await findProduct(product.handle);
  if (existing && options.upload) {
    const deleted = await deleteMedia(existing);
    if (deleted) console.log(`  removed ${deleted} existing images`);
  }

  const input = buildProductInput(product);
  if (options.upload) {
    for (const [index, image] of product.images.entries()) {
      const file = await stageImage(product, image);
      input.files[index].originalSource = file.originalSource;
      console.log(`  staged ${image.uid} ${image.localFile}`);
    }
  } else {
    input.files = [];
    for (const variant of input.variants) delete variant.file;
  }

  const canPublish =
    options.publish &&
    product.readiness.launchReady &&
    input.variants.every((variant) => variant.price !== "0.00");
  input.status = canPublish ? "ACTIVE" : "DRAFT";

  const identifier = existing ? { id: existing.id } : { handle: product.handle };
  let data;
  try {
    data = await admin(PRODUCT_SET, { identifier, input, synchronous: true });
  } catch (error) {
    if (existing) throw error;
    console.warn(`${product.handle}: handle identifier failed, retrying create`);
    data = await admin(PRODUCT_SET, { input, synchronous: true });
  }
  const errors = data.productSet.userErrors;
  if (errors.length) throw new Error(`${product.handle}: ${JSON.stringify(errors)}`);

  const productId = data.productSet.product.id;
  const metafields = await setMetafields(product, productId);
  const published = canPublish ? await publishProduct(productId) : false;
  return {
    created: !existing,
    id: productId,
    metafields,
    published,
    status: input.status,
  };
}

async function verifyProducts(products) {
  const expected = new Map(products.map((product) => [product.handle, product]));
  const found = new Map();
  let after = null;
  do {
    const data = await admin(VERIFY_PRODUCTS, { after, first: 250 });
    for (const product of data.products.nodes) {
      if (expected.has(product.handle)) found.set(product.handle, product);
    }
    after = data.products.pageInfo.hasNextPage ? data.products.pageInfo.endCursor : null;
  } while (after);

  const result = {
    mediaCountMismatches: [],
    missing: [],
    optionMismatches: [],
    passed: true,
    priceMismatches: [],
    skuMismatches: [],
    statusMismatches: [],
    variantCountMismatches: [],
  };
  const expectedOptions = ["Colour", "Size"];
  const expectedSizes = ["XS", "S", "M", "L", "XL", "XXL"];

  for (const [handle, product] of expected) {
    const remote = found.get(handle);
    if (!remote) {
      result.missing.push(handle);
      continue;
    }
    const expectedStatus = product.readiness.launchReady && publish ? "ACTIVE" : "DRAFT";
    if (remote.status !== expectedStatus) {
      result.statusMismatches.push({ actual: remote.status, expected: expectedStatus, handle });
    }
    const remoteVariants = remote.variants.nodes;
    if (remoteVariants.length !== product.variants.length) {
      result.variantCountMismatches.push({
        actual: remoteVariants.length,
        expected: product.variants.length,
        handle,
      });
    }
    if (remote.mediaCount.count !== product.imageCount) {
      result.mediaCountMismatches.push({
        actual: remote.mediaCount.count,
        expected: product.imageCount,
        handle,
      });
    }
    const optionNames = remote.options.map((option) => option.name);
    if (
      optionNames.length !== expectedOptions.length ||
      optionNames.some((name, index) => name !== expectedOptions[index])
    ) {
      result.optionMismatches.push({ actual: optionNames, expected: expectedOptions, handle });
    } else {
      const colourValues = remote.options[0]?.values ?? [];
      const sizeValues = remote.options[1]?.values ?? [];
      const expectedColours = product.colourways.map((colourway) => colourway.name);
      if (
        colourValues.length !== expectedColours.length ||
        expectedColours.some((colour) => !colourValues.includes(colour)) ||
        expectedSizes.some((size) => !sizeValues.includes(size))
      ) {
        result.optionMismatches.push({
          actual: { colourValues, sizeValues },
          expected: { colourValues: expectedColours, sizeValues: expectedSizes },
          handle,
        });
      }
    }

    const expectedBySku = new Map(product.variants.map((variant) => [variant.sku, variant]));
    for (const remoteVariant of remoteVariants) {
      const variant = expectedBySku.get(remoteVariant.sku);
      if (!variant) {
        result.skuMismatches.push({ actual: remoteVariant.sku, handle });
        continue;
      }
      const expectedPrice = variant.price == null ? "0.00" : Number(variant.price).toFixed(2);
      if (Number(remoteVariant.price).toFixed(2) !== expectedPrice) {
        result.priceMismatches.push({
          actual: remoteVariant.price,
          expected: expectedPrice,
          handle,
          sku: variant.sku,
        });
      }
    }
  }

  result.passed =
    result.missing.length === 0 &&
    result.statusMismatches.length === 0 &&
    result.variantCountMismatches.length === 0 &&
    result.mediaCountMismatches.length === 0 &&
    result.optionMismatches.length === 0 &&
    result.skuMismatches.length === 0 &&
    result.priceMismatches.length === 0;
  result.totals = {
    images: products.reduce((total, product) => total + product.imageCount, 0),
    products: products.length,
    variants: products.reduce((total, product) => total + product.variants.length, 0),
  };
  return result;
}

async function verifyCollections(products) {
  const result = {
    checked: 0,
    missingCollections: [],
    missingMemberships: [],
    passed: true,
  };
  for (const collection of JSON.parse(readFileSync(fixturePath, "utf8")).collections) {
    const expected = products
      .filter((product) => product.collections.includes(collection.sourceName))
      .map((product) => product.handle);
    if (expected.length === 0) continue;
    const data = await admin(COLLECTION_BY_HANDLE, { query: `handle:${collection.handle}` });
    const found = data.collections.nodes.find((node) => node.handle === collection.handle);
    if (!found) {
      result.missingCollections.push(collection.handle);
      continue;
    }
    result.checked += 1;
    const memberHandles = new Set();
    let after = null;
    do {
      const members = await admin(COLLECTION_PRODUCTS, { after, id: found.id });
      for (const member of members.collection.products.nodes) memberHandles.add(member.handle);
      after = members.collection.products.pageInfo.hasNextPage
        ? members.collection.products.pageInfo.endCursor
        : null;
    } while (after);
    for (const handle of expected) {
      if (!memberHandles.has(handle)) {
        result.missingMemberships.push({ collection: collection.handle, handle });
      }
    }
  }
  result.passed = result.missingCollections.length === 0 && result.missingMemberships.length === 0;
  return result;
}

async function main() {
  const startedAt = new Date().toISOString();
  const fixture = JSON.parse(readFileSync(fixturePath, "utf8"));
  const products = selectedProducts(fixture);
  if (products.length === 0) throw new Error("No products selected.");

  if (!dryRun && !verifyOnly && !collectionsOnly && upload && !existsSync(imageDir)) {
    throw new Error(`Image folder not found: ${imageDir}. Pass --image-dir.`);
  }
  if (!verifyOnly && !collectionsOnly) {
    for (const product of products) {
      for (const image of product.images) {
        if (!image.localFile) throw new Error(`${product.handle}: ${image.uid} has no local file`);
        if (upload && !existsSync(join(imageDir, image.localFile))) {
          throw new Error(`${product.handle}: missing ${join(imageDir, image.localFile)}`);
        }
      }
    }
  }

  const report = {
    collections: { created: 0, ensured: 0, failed: 0, membershipAdded: 0 },
    dryRun,
    errors: [],
    finishedAt: null,
    imageFolder: imageDir,
    images: { assigned: 0, uploaded: 0 },
    metafields: { failed: 0, set: 0 },
    mode: dryRun ? "dry-run" : upload ? "upload" : "no-upload",
    products: { created: 0, draft: 0, failed: 0, published: 0, updated: 0 },
    startedAt,
    variants: { expected: products.reduce((total, product) => total + product.variants.length, 0) },
    verification: null,
  };

  if (dryRun) {
    for (const product of products) {
      console.log(
        `${product.handle}: ${product.variants.length} variants, ${product.imageCount} images, ` +
          `${product.readiness.verdict}, blockers=${product.readiness.launchBlockers.join(",") || "none"}, ` +
          `collections=${product.collections.join(",")}`,
      );
    }
    console.log("\nfirst product input:");
    console.log(JSON.stringify(buildProductInput(products[0]), null, 2));
    report.finishedAt = new Date().toISOString();
    report.images.assigned = products.reduce((total, product) => total + product.imageCount, 0);
    report.products.draft = products.length;
    mkdirSync(dirname(reportPath), { recursive: true });
    writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`\nwrote ${reportPath}`);
    return;
  }

  const settings = await admin(SHOP_SETTINGS);
  report.shop = settings.shop;
  console.log(`shop ${settings.shop.name} (${settings.shop.currencyCode})`);

  if (verifyOnly) {
    report.mode = "verify-only";
    report.verification = await verifyProducts(products);
    report.verification.collections = await verifyCollections(products);
    report.verification.passed =
      report.verification.passed && report.verification.collections.passed;
    report.images.assigned = products.reduce((total, product) => total + product.imageCount, 0);
    report.products.draft = report.verification.passed ? products.length : 0;
    report.finishedAt = new Date().toISOString();
    mkdirSync(dirname(reportPath), { recursive: true });
    writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`);
    console.log(`verification: ${report.verification.passed ? "passed" : "failed"}`);
    console.log(JSON.stringify(report.verification.totals));
    console.log(`wrote ${reportPath}`);
    if (!report.verification.passed) process.exit(1);
    return;
  }

  const collections = fixture.collections.filter((collection) =>
    products.some((product) => product.collections.includes(collection.sourceName)),
  );
  const collectionIds = new Map();
  for (const collection of collections) {
    try {
      const ensured = await ensureCollection(collection);
      collectionIds.set(collection.handle, ensured.id);
      report.collections.ensured += 1;
      if (ensured.created) report.collections.created += 1;
      console.log(`${ensured.created ? "created" : "ensured"} collection ${collection.handle}`);
    } catch (error) {
      console.error(`failed collection ${collection.handle}: ${error.message}`);
      report.errors.push({ collection: collection.handle, error: error.message });
      report.collections.failed += 1;
    }
  }

  const productIdsByHandle = new Map();
  if (collectionsOnly) {
    const existingIds = await listProductIds();
    for (const product of products) {
      const id = existingIds.get(product.handle);
      if (id) productIdsByHandle.set(product.handle, id);
    }
    report.mode = "collections-only";
  } else {
    for (const [index, product] of products.entries()) {
      console.log(`[${index + 1}/${products.length}] ${product.handle}`);
      try {
        const result = await importProduct(product, { dryRun, publish, upload });
        productIdsByHandle.set(product.handle, result.id);
        report.images.uploaded += upload ? product.imageCount : 0;
        report.images.assigned += product.imageCount;
        report.metafields.set += result.metafields;
        if (result.created) report.products.created += 1;
        else report.products.updated += 1;
        if (result.status === "DRAFT") report.products.draft += 1;
        if (result.published) report.products.published += 1;
        console.log(
          `  ${result.created ? "created" : "updated"} ${product.handle} (${product.variants.length} variants, ${product.imageCount} images, ${result.status})`,
        );
      } catch (error) {
        console.error(`failed ${product.handle}: ${error.message}`);
        report.errors.push({ error: error.message, product: product.handle });
        report.products.failed += 1;
      }
      await sleep(300);
    }
  }

  for (const collection of collections) {
    const collectionId = collectionIds.get(collection.handle);
    if (!collectionId) continue;
    const desiredIds = products
      .filter((product) => product.collections.includes(collection.sourceName))
      .map((product) => productIdsByHandle.get(product.handle))
      .filter(Boolean);
    if (desiredIds.length === 0) continue;
    try {
      const currentIds = await collectionProductIds(collectionId);
      const current = new Set(currentIds);
      const missing = desiredIds.filter((id) => !current.has(id));
      if (missing.length === 0) continue;
      const data = await admin(COLLECTION_ADD, { id: collectionId, productIds: missing });
      const errors = data.collectionAddProducts.userErrors;
      if (errors.length) throw new Error(JSON.stringify(errors));
      report.collections.membershipAdded += missing.length;
      console.log(`added ${missing.length} products to ${collection.handle}`);
    } catch (error) {
      console.error(`failed collection membership ${collection.handle}: ${error.message}`);
      report.errors.push({ collection: collection.handle, error: error.message });
      report.collections.failed += 1;
    }
    await sleep(150);
  }

  const imported = products.filter((product) => productIdsByHandle.has(product.handle));
  report.verification = await verifyProducts(imported);
  report.verification.collections = await verifyCollections(imported);
  report.verification.passed = report.verification.passed && report.verification.collections.passed;
  report.finishedAt = new Date().toISOString();
  mkdirSync(dirname(reportPath), { recursive: true });
  writeFileSync(reportPath, `${JSON.stringify(report, null, 2)}\n`);

  console.log(
    `\nproducts: ${report.products.created} created, ${report.products.updated} updated, ` +
      `${report.products.failed} failed, ${report.products.draft} draft, ${report.products.published} published`,
  );
  console.log(
    `variants: ${report.variants.expected}; images: ${report.images.uploaded} uploaded / ${report.images.assigned} assigned; ` +
      `collections: ${report.collections.created} created, ${report.collections.ensured} ensured, ${report.collections.membershipAdded} memberships`,
  );
  console.log(`verification: ${report.verification.passed ? "passed" : "failed"}`);
  console.log(JSON.stringify(report.verification.totals));
  console.log(`wrote ${reportPath}`);
  if (report.errors.length > 0 || !report.verification.passed) process.exit(1);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
